<?php
if (!defined('ABSPATH')) {
    exit; // Exit if accessed directly.
}

/**
 * Register a compiled entry from the build directory.
 *
 * Reads the dependencies and version hash generated by @wordpress/scripts
 * and registers a script and a style under the same handle.
 *
 * @since 1.1.0
 * @author Monzur Alam
 *
 * @param string $handle Script/style handle.
 * @param string $entry  Entry name in the build directory (e.g. 'frontend').
 * @return bool Whether the entry was registered.
 */
if (!function_exists('uts_register_build')) {
    function uts_register_build($handle, $entry) {
        $asset_file = UTS_BUILD . '/' . $entry . '.asset.php';

        if (!file_exists($asset_file)) {
            return false;
        }

        $asset = require $asset_file;

        if (file_exists(UTS_BUILD . '/' . $entry . '.css')) {
            wp_register_style($handle, UTS_BUILD_URL . '/' . $entry . '.css', array(), $asset['version'], 'all');
            wp_style_add_data($handle, 'rtl', 'replace');
        }

        wp_register_script($handle, UTS_BUILD_URL . '/' . $entry . '.js', $asset['dependencies'], $asset['version'], true);

        return true;
    }
}

/**
 * Enqueue the frontend assets.
 *
 * Called from the shortcode, so it also works for shortcodes in widgets
 * or page builders that the early check below can't see.
 *
 * @since 1.1.0
 * @author Monzur Alam
 */
if (!function_exists('uts_enqueue_frontend')) {
    function uts_enqueue_frontend() {
        wp_enqueue_style('uts');
        wp_enqueue_script('uts');
    }
}

/**
 * Register frontend assets, and enqueue them early when the current
 * post contains the shortcode (so the CSS loads in the head).
 *
 * @since 1.0.0
 * @author Monzur Alam
 */
if (!function_exists('uts_assets')) {
    function uts_assets() {
        uts_register_build('uts', 'frontend');

        $post = get_post();

        if (is_singular() && $post && has_shortcode($post->post_content, 'uts')) {
            uts_enqueue_frontend();
        }
    }
    add_action('wp_enqueue_scripts', 'uts_assets');
}

/**
 * Admin assets, loaded only on the plugin's own screens.
 *
 * @since 1.0.1
 * @author Monzur Alam
 */
if (!function_exists('uts_admin_assets')) {
    function uts_admin_assets() {
        $screen = get_current_screen();

        if (!$screen || 'uts' !== $screen->post_type) {
            return;
        }

        if (uts_register_build('uts-admin', 'admin')) {
            wp_enqueue_style('uts-admin');
            wp_enqueue_script('uts-admin');
        }
    }
    add_action('admin_enqueue_scripts', 'uts_admin_assets');
}
